// План specs/usage-tracking.md 1.3 (кейс .qa/tests/usage-tracking/UT-03). Владелец (admin), компания «test», десктоп, EN.
// @writes: создаёт работу «QA-AUTO usage #04d347 …» (клиент QA-quota client, БЕЗ техников — SMS не уходит) и в конце
// переводит её в Cancelled (удаления работ в интерфейсе нет; событие «Jobs created» при этом остаётся — так задумано).
// Запросы send-sms перехватываются и обрываются. В конце selected-company-id возвращается на «test».
import { test, expect } from '../../fixtures';
import { blockSmsSending, expectNoSmsSent, openNewJob } from '../dispatch-sms/dispatch-helpers';
import { setJobStatus } from '../job-closed-date/closed-helpers';
import { counterValue, openUsage, refreshUsage, restoreTest, startInTest } from './usage-helpers';

test.describe('Usage tracking: events increment counters (#04d347)', () => {
  test('Owner: creating a job increments Jobs created by 1 on Activity & usage (This month) #04d347 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(180_000);
    const owner = await asUser('admin');
    await startInTest(owner);
    const smsHits = await blockSmsSending(owner);
    let jobUrl = '';
    try {
      // 1. Счётчик до.
      expect(await openUsage(owner)).toBe(200);
      const before = await counterValue(owner, 'Jobs created');

      // 2. New Job без техника → Create Job.
      const title = `QA-AUTO usage #04d347 ${Date.now().toString(36)}`;
      await openNewJob(owner, 'en');
      const client = owner.getByLabel('Client Name *');
      await client.pressSequentially('QA-quota', { delay: 20 });
      await owner.getByRole('button').filter({ hasText: 'QA-quota client' }).first().click();
      await expect(client).toHaveValue('QA-quota client');
      await expect(owner.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
      await owner.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
      await owner.getByRole('option', { name: 'Repair', exact: true }).click();
      await owner.getByLabel('Job Description').fill(title);
      await owner.getByRole('button', { name: 'Create Job', exact: true }).click();
      await owner.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
      jobUrl = owner.url().replace(/&tab=items/, '');

      // 3. Счётчик после: +1 (≥, если параллельно кто-то ещё создал работу в «test»).
      // Источник: AC «יצירת עבודה → אירוע נרשם; מסך אנליטיקס → מונים מצטברים».
      expect(await openUsage(owner)).toBe(200);
      await expect.poll(async () => {
        const now = await counterValue(owner, 'Jobs created');
        if (now < before + 1) await refreshUsage(owner);
        return now;
      }, { message: `Jobs created: было ${before}, ждём ≥ ${before + 1}`, timeout: 30_000 }).toBeGreaterThanOrEqual(before + 1);
    } finally {
      // 4. Очистка: работа QA-AUTO → Cancelled.
      if (jobUrl) {
        await owner.goto(jobUrl);
        await setJobStatus(owner, 'Cancelled');
      }
      await restoreTest(owner);
    }
    expectNoSmsSent(smsHits);
  });
});
